window.BABA.NarrationEN = {"questNames":{"text":"The cells are open. The prisoners show you the transport route.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":4.56,"audio":"","chapter":1},"questVerdict":{"text":"The captives’ chains are broken. The grave warden guards the passage to the shore.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.496,"audio":"","chapter":1},"questBell":{"text":"The prisoners aboard the ship are free. The bell no longer commands them.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.088,"audio":"","chapter":2},"questMemory":{"text":"The dark shipment is halted. The road to the ruins is revealed.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":4.872,"audio":"","chapter":2},"questKing":{"text":"The victims’ bonds are broken. The voices inside the stone fall silent.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.496,"audio":"","chapter":3},"questEcho":{"text":"The cavern passage is open. You found the road to the forge.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":4.488,"audio":"","chapter":3},"questPrisoner":{"text":"The forge prisoners are free. They will no longer feed the fire.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":4.608,"audio":"","chapter":4},"questHeart":{"text":"You control the final gate mechanism. Head for the court.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":4.488,"audio":"","chapter":4},"ruinsIntro":{"text":"This is what the Qadi calls salvation. His victims cannot die. The earth holds them bound.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":7.344,"audio":"","chapter":3},"ruinsCheckpoint":{"text":"The stone is safe. Head for the cavern’s final passage.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":4.512,"audio":"","chapter":3},"ruinsBoss":{"text":"The Sacrifice Warden guards the Qadi’s road. Break through.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":4.584,"audio":"","chapter":3},"ruinsWin":{"text":"The warden has fallen. Heat rises from the forge beneath the cavern.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.04,"audio":"","chapter":3},"forgeIntro":{"text":"The guards’ weapons and the prisoners’ chains are forged here. You have reached the Qadi’s furnace.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":6.216,"audio":"","chapter":4},"forgeCheckpoint":{"text":"Catch your breath away from the embers. The forge master holds the final gate.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.616,"audio":"","chapter":4},"forgeBoss":{"text":"The Forge Master approaches. This time he faces his own iron.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.112,"audio":"","chapter":4},"forgeWin":{"text":"The forge is silent. No more chains will be made. The road to the Final Court is open.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":7.224,"audio":"","chapter":4},"coastIntro":{"text":"This port trades in people. The Qadi’s ships bring prisoners here.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":4.848,"audio":"","chapter":2},"coastRoots":{"text":"Roots coil around the victims buried on the shore. The earth will not let them go.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.616,"audio":"","chapter":2},"coastStreet":{"text":"The houses were emptied. Marks on the doors count the prisoners.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":4.584,"audio":"","chapter":2},"coastPier":{"text":"The lanterns guide the slave ships. There are living people inside.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.016,"audio":"","chapter":2},"coastSquare":{"text":"Nameless graves lie beneath the square. The port master knows the numbers, not the names.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":6.672,"audio":"","chapter":2},"coastCheckpoint":{"text":"Catch your breath beside the lantern. The road to the belfry is clear.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":4.896,"audio":"","chapter":2},"coastBoss":{"text":"The port master calls his hunters with the bell. Silence it.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":4.68,"audio":"","chapter":2},"coastDeath":{"text":"The sea did not take you. Return to shore and rise.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":4.344,"audio":"","chapter":2},"coastDeath2":{"text":"The roots could not hold you. Walk again.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":3.264,"audio":"","chapter":2},"coastDeath3":{"text":"The bell still tolls. You will not remain on this shore.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":4.296,"audio":"","chapter":2},"coastSeal":{"text":"The transport route is opening. Head inland.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":3.864,"audio":"","chapter":2},"coastWin":{"text":"The bell is silent. The prisoners’ transport has stopped. The road to the Qadi runs through the ruins.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":7.776,"audio":"","chapter":2},"intro":{"text":"They buried you alive, Bahtiyar. You broke the stone lid. Break the prisoners’ chains and leave this grave.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":7.68,"audio":"","chapter":1},"chains":{"text":"Living prisoners remain at the ends of these chains. Open the cells.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.184,"audio":"","chapter":1},"ritual":{"text":"The wounded were never brought here to heal. Their suffering feeds the Qadi’s ritual.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.712,"audio":"","chapter":1},"crypt":{"text":"The altar is still warm. This grave is the first stop for the sacrifices.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.664,"audio":"","chapter":1},"rot":{"text":"Bones are built into the walls. The Qadi will not release even his dead.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.544,"audio":"","chapter":1},"checkpoint":{"text":"Catch your breath beside the stone. Your road is not over.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":4.344,"audio":"","chapter":1},"boss":{"text":"The Grave Warden holds the passage. The road to the port lies behind him.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":5.4,"audio":"","chapter":1},"heroOath":{"text":"You buried me. Now it is your turn.","speaker":"Bahtiyar","voice":"en-US-EricNeural","style":"D","duration":3.48,"audio":"","chapter":1},"cellat":{"text":"The Qadi wants you alive. You will return to your coffin.","speaker":"Grave Warden","voice":"en-US-ChristopherNeural","style":"D","duration":4.8,"audio":"","chapter":1},"seal":{"text":"Another chain is broken. Keep moving.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":3.312,"audio":"","chapter":1},"death":{"text":"You are still breathing. Get up.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":2.832,"audio":"","chapter":1},"death2":{"text":"This grave cannot hold you. Try again.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":3.528,"audio":"","chapter":1},"death3":{"text":"You broke the stone lid. Do not give up here.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":3.528,"audio":"","chapter":1},"win":{"text":"The warden has fallen. The road to the slave port is open.","speaker":"Narrator","voice":"en-US-SteffanNeural","style":"D","duration":4.632,"audio":"","chapter":1}};
